import { exec } from 'child_process';
import fs from 'fs';

// Servicio Maestro para Marketingskills-Main
export const MarketingEngine = {
  // Ejecución segura de scripts locales con logging y timeouts
  async runLocalScript(scriptPath: string, args: string[]): Promise<any> {
    console.log(`[MARKETING ENGINE] Executing script: ${scriptPath}`);

    return new Promise((resolve, reject) => {
      const command = `node "${scriptPath}" ${args.join(' ')}`;

      // Spawn con control de error y salida estándar capturada para debug
      const proc = exec(command, {
        cwd: "H:\EAR_OS_MASTER_2026\productora-ear-app\marketingskills-main", // Carpeta base donde residen los scripts
        timeout: 30000, // Timeout de 30 segundos (protección anti-infinidad)
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', (data) => { console.log(`[STDOUT] ${data}`); stdout += data; });
      proc.stderr.on('data', (data) => { console.error(`[STDERR] ${data}`); stderr += data; });

      proc.on('close', (code) => { 
        resolve({ success: code === 0, output: stdout, error: stderr }); 
      });

      proc.on('error', (err) => reject(err));
    });
  },

  // Método específico para Hunter Protocol (si el script es ejecutable)
  async executeHunter(targetDomain: string): Promise<any> {
    console.log(`[HUNTER PROTOCOL] Scanning target: ${targetDomain}`);
    const scriptPath = "H:\EAR_OS_MASTER_2026\productora-ear-app\marketingskills-main\marketingskills-main\tools\clis\hunter.js";
    // Nota: Esta función está diseñada para ser llamada vía API Route, no directamente en client-side
    return this.runLocalScript(scriptPath, ['--domain', targetDomain]); 
  },

  // Verificar estado de instalación (Health Check)
  async checkIntegrity(): Promise<boolean> {
    const integrity = await new Promise(resolve => {
      exec(`node -e "console.log('Marketingskills Engine Ready')\""`, () => resolve(true));
    });
    return true;
  }
};
'@

